// NewGetGuardrailResponseBody builds the HTTP response body from the result of
// the "getGuardrail" endpoint of the "intentPolicies" service.
func NewGetGuardrailResponseBody(res *intentpolicies.IntentGuardrail) *GetGuardrailResponseBody {
	body := &GetGuardrailResponseBody{
		ID:      res.ID,
		Version: res.Version,
	}
	if res.Statements != nil {
		body.Statements = make([]string, len(res.Statements))
		for i, val := range res.Statements {
			body.Statements[i] = val
		}
	} else {
		body.Statements = []string{}
	}
	if res.Questions != nil {
		body.Questions = make([]*IntentLabelQuestionResponseBody, len(res.Questions))
		for i, val := range res.Questions {
			if val == nil {
				body.Questions[i] = nil
				continue
			}
			body.Questions[i] = marshalIntentpoliciesIntentLabelQuestionToIntentLabelQuestionResponseBody(val)
		}
	} else {
		body.Questions = []*IntentLabelQuestionResponseBody{}
	}
	if res.Contracts != nil {
		body.Contracts = make([]*IntentContractResponseBody, len(res.Contracts))
		for i, val := range res.Contracts {
			if val == nil {
				body.Contracts[i] = nil
				continue
			}
			body.Contracts[i] = marshalIntentpoliciesIntentContractToIntentContractResponseBody(val)
		}
	} else {
		body.Contracts = []*IntentContractResponseBody{}
	}
	return body
}

// NewAnalyzeSessionResponseBody builds the HTTP response body from the result
// of the "analyzeSession" endpoint of the "intentPolicies" service.
func NewAnalyzeSessionResponseBody(res *intentpolicies.IntentSessionAnalysis) *AnalyzeSessionResponseBody {
	body := &AnalyzeSessionResponseBody{
		ChatID:           res.ChatID,
		Generation:       res.Generation,
		GuardrailVersion: res.GuardrailVersion,
		LimitHit:         res.LimitHit,
	}
	if res.Evaluator != nil {
		body.Evaluator = marshalIntentpoliciesIntentEvaluatorDescriptorToIntentEvaluatorDescriptorResponseBody(res.Evaluator)
	}
	if res.Assessments != nil {
		body.Assessments = make([]*IntentCallAssessmentResponseBody, len(res.Assessments))
		for i, val := range res.Assessments {
			if val == nil {
				body.Assessments[i] = nil
				continue
			}
			body.Assessments[i] = marshalIntentpoliciesIntentCallAssessmentToIntentCallAssessmentResponseBody(val)
		}
	} else {
		body.Assessments = []*IntentCallAssessmentResponseBody{}
	}
	if res.Totals != nil {
		body.Totals = marshalIntentpoliciesIntentAnalysisTotalsToIntentAnalysisTotalsResponseBody(res.Totals)
	}
	return body
}

