// ValidateAnalyzeSessionRequestBody runs the validations defined on
// AnalyzeSessionRequestBody
func ValidateAnalyzeSessionRequestBody(body *AnalyzeSessionRequestBody) (err error) {
	if body.ChatID == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("chat_id", "body"))
	}
	if body.Evaluator == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("evaluator", "body"))
	}
	if body.ChatID != nil {
		err = goa.MergeErrors(err, goa.ValidateFormat("body.chat_id", *body.ChatID, goa.FormatUUID))
	}
	if body.Evaluator != nil {
		if !(*body.Evaluator == "jev" || *body.Evaluator == "gemini") {
			err = goa.MergeErrors(err, goa.InvalidEnumValueError("body.evaluator", *body.Evaluator, []any{"jev", "gemini"}))
		}
	}
	if body.Generation != nil {
		if *body.Generation < 0 {
			err = goa.MergeErrors(err, goa.InvalidRangeError("body.generation", *body.Generation, 0, true))
		}
	}
	if body.Offset != nil {
		if *body.Offset < 0 {
			err = goa.MergeErrors(err, goa.InvalidRangeError("body.offset", *body.Offset, 0, true))
		}
	}
	if body.Limit != nil {
		if *body.Limit < 1 {
			err = goa.MergeErrors(err, goa.InvalidRangeError("body.limit", *body.Limit, 1, true))
		}
	}
	if body.Limit != nil {
		if *body.Limit > 200 {
			err = goa.MergeErrors(err, goa.InvalidRangeError("body.limit", *body.Limit, 200, false))
		}
	}
	return
}

// ValidateUploadTranscriptRequestBody runs the validations defined on
// UploadTranscriptRequestBody
func ValidateUploadTranscriptRequestBody(body *UploadTranscriptRequestBody) (err error) {
	if body.Name == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("name", "body"))
	}
	if body.Content == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("content", "body"))
	}
	if body.Name != nil {
		if utf8.RuneCountInString(*body.Name) < 1 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("body.name", *body.Name, utf8.RuneCountInString(*body.Name), 1, true))
		}
	}
	if body.Name != nil {
		if utf8.RuneCountInString(*body.Name) > 255 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("body.name", *body.Name, utf8.RuneCountInString(*body.Name), 255, false))
		}
	}
	if body.Content != nil {
		if utf8.RuneCountInString(*body.Content) < 1 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("body.content", *body.Content, utf8.RuneCountInString(*body.Content), 1, true))
		}
	}
	if body.Content != nil {
		if utf8.RuneCountInString(*body.Content) > 20971520 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("body.content", *body.Content, utf8.RuneCountInString(*body.Content), 20971520, false))
		}
	}
	return
}
